echo "Downloading ${#ids[@]} icons..."
for id in "${ids[@]}"; do
  if [ ! -f "icons/$id.png" ]; then
    curl -sfL "https://render.albiononline.com/v1/spell/$id.png?size=217" -o "icons/$id.png" \
      && echo "  ok  $id" || echo "  MISS $id"
    sleep 0.05
  fi
done
echo "Done. ${#ids[@]} requested; see icons/ folder."
